package com.bank.ledger.service;

import java.util.logging.Logger;

// Finds a balance in a sorted array whose direction is unknown.
public class LedgerSearchService {
    private static final Logger log = Logger.getLogger(LedgerSearchService.class.getName());

    public int search(int[] balances, int key) {
        int start = 0, end = balances.length - 1;
        boolean asc = balances[start] < balances[end]; // detect order once
        log.fine(() -> "Detected order ascending=" + asc);
        while (start <= end) {
            int mid = start + (end - start) / 2; // overflow-safe midpoint
            if (balances[mid] == key) {
                final int found = mid;
                log.info(() -> "Found key " + key + " at index " + found);
                return mid;
            }
            if (asc) {
                if (key < balances[mid]) end = mid - 1; else start = mid + 1;
            } else {
                if (key > balances[mid]) end = mid - 1; else start = mid + 1;
            }
        }
        log.warning(() -> "Key " + key + " not found");
        return -1;
    }
}
